queries.cql:
// CrowdStrike CQL for Geographic Impossibility Login
// Repository: flame-banking-auth-logs
// Groups logins by user within 60m windows and flags when
// multiple distinct countries appear (physical travel impossible)
(event_type="login_success" OR event_type="login_attempt")
| groupBy(user_id, function=[
    count(as=login_count),
    collect([geo_country, src_ip, @timestamp]),
    selectFirst(geo_country, as=first_country),
    selectLast(geo_country, as=last_country),
    min(@timestamp, as=first_time),
    max(@timestamp, as=last_time)
  ], span=60m)
| login_count >= 2
| first_country != last_country
